import {topics,searchNotes,inferTopic,buildPlan,newVault} from './core.js';

import {removeRecord,restoreLast,moveRecord} from './management.js';
import {bindImagePicker} from './image-picker.js';
let activeImagePicker=null;
let archiveEditing=false,searchEditing=false;
function tabHero(title,subtitle){return `<div class="journal-title tab-hero"><h1 class="en">${title}</h1><p>${subtitle}</p></div>`;}
function recallReason(note,q,fallback){const fragments=[];for(let i=0;i<q.length-1;i++){const s=q.slice(i,i+2);if(!/[\s，。？、]/.test(s)&&note.reason?.includes(s)&&!['一个','之前','地方','可以','的地'].includes(s))fragments.push(s);}const hits=[...new Set(fragments)].slice(0,3);return hits.length?'匹配到你备注中的「'+hits.join('」「')+'」':fallback.startsWith('你的备注：')?'想起你当时写下的：'+note.reason:'收藏中的线索：'+fallback;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='archive-mode'){archiveEditing=!archiveEditing;archiveSelection.clear();renderOrganize();}if(b.dataset.action==='search-mode'){searchEditing=!searchEditing;selection.clear();renderResults();}});
let holdTimer,holdStart,ignoreClickUntil=0;
document.addEventListener('pointerdown',e=>{if(modal.open||e.button!==0||!['library','organize'].includes(view))return;const row=e.target.closest('.note-row[data-id]');if(!row)return;holdStart={x:e.clientX,y:e.clientY};holdTimer=setTimeout(()=>{holdTimer=null;ignoreClickUntil=Date.now()+900;archiveEditing=true;archiveFilter='all';archiveSelection=new Set([row.dataset.id]);view='organize';group=null;render();toast('已进入批量编辑');},600);});
document.addEventListener('pointermove',e=>{if(holdTimer&&holdStart&&Math.hypot(e.clientX-holdStart.x,e.clientY-holdStart.y)>10){clearTimeout(holdTimer);holdTimer=null;}});
for(const event of ['pointerup','pointercancel','scroll'])document.addEventListener(event,()=>{clearTimeout(holdTimer);holdTimer=null;},true);
document.addEventListener('click',e=>{if(Date.now()<ignoreClickUntil){e.preventDefault();e.stopImmediatePropagation();}},true);
let archiveSelection=new Set(),archiveFilter='pending';
function renderOrganize(){const archived=new Set(vault.collections.flatMap(c=>c.noteIds)),ns=vault.notes.filter(n=>archiveFilter==='all'||!archived.has(n.id));archiveSelection=new Set([...archiveSelection].filter(id=>vault.notes.some(n=>n.id===id)));main.innerHTML=`<button class="text-btn" data-action="home">${icon('back')}回到记忆</button><div class="organize-intro"><span class="brand-kicker">A place for every little thing</span><h1>给喜欢，找个位置。</h1><p>归入合集，不必再从头翻找。</p></div><div class="section-head"><h2>我的合集</h2><button class="text-btn" data-action="collection">新建合集</button></div><div class="archive-collections">${vault.collections.map(c=>`<button data-action="archive-open" data-id="${c.id}">${safeImage(c.cover)?`<img class="collection-thumb" src="${esc(safeImage(c.cover))}" alt="">`:icon('folder')}<span><b>${esc(c.name)}</b><small>${c.noteIds.filter(id=>vault.notes.some(n=>n.id===id)).length} 条收藏</small></span>${icon('chevron')}</button>`).join('')||'<p class="helper">可以先选择收藏，再创建你的第一个合集。</p>'}</div><div class="section-head"><h2>整理收藏</h2><button class="text-btn" data-action="archive-mode">${archiveEditing?'完成编辑':'批量编辑'}</button></div><div class="segmented">${[['pending','待归档'],['all','全部收藏']].map(([v,t])=>`<button class="${archiveFilter===v?'selected':''}" data-action="archive-filter" data-id="${v}">${t}${v==='pending'?' · '+vault.notes.filter(n=>!archived.has(n.id)).length:''}</button>`).join('')}</div>${archiveEditing?'<button class="text-btn" data-action="archive-all">全选 / 取消全选</button>':''}<div class="memory-paper">${ns.map(n=>archiveEditing?`<label class="archive-note"><input type="checkbox" value="${n.id}" data-archive-check ${archiveSelection.has(n.id)?'checked':''}>${thumb(n)}<span><b>${esc(n.title)}</b><small>${esc(n.reason||n.body.slice(0,55))}</small><em>${vault.collections.filter(c=>c.noteIds.includes(n.id)).map(c=>esc(c.name)).join(' · ')||'尚未归档'}</em></span></label>`:row(n)).join('')||'<div class="empty">都整理好了。新收藏也会出现在这里。</div>'}</div><div id="archive-bar"></div><p class="library-footer">归档只整理合集，不会移除原收藏；一条收藏可以放进多个合集。</p>`;archiveBar();}
function archiveBar(){const el=document.querySelector('#archive-bar');if(el)el.innerHTML=archiveEditing&&archiveSelection.size?`<div class="selected-bar"><span>已选 ${archiveSelection.size} 条</span><button data-action="archive-save">归入合集</button></div>`:'';}
function archiveSave(){if(!archiveSelection.size)return;openModal('归入合集',`<form id="archive-form"><p class="lede">为 ${archiveSelection.size} 条收藏找个位置。</p><label class="label">选择合集</label><select class="field" name="collection"><option value="">新建合集</option>${vault.collections.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><label class="label" id="archive-name-label">新合集名称</label><input class="field" name="name" maxlength="80" placeholder="例如：想和朋友一起去"><div id="archive-error"></div><button class="solid">完成归档</button></form>`);const f=document.querySelector('#archive-form');f.elements.collection.onchange=()=>{const hide=!!f.elements.collection.value;f.elements.name.hidden=hide;document.querySelector('#archive-name-label').hidden=hide;};f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('.solid');b.disabled=true;try{const id=f.elements.collection.value,name=f.elements.name.value.trim();if(!id&&!name)throw Error('给新合集起个名字吧');const ids=[...archiveSelection];await commit(v=>{if(id){const c=v.collections.find(c=>c.id===id);c.noteIds=[...new Set([...c.noteIds,...ids])];}else v.collections.push({id:crypto.randomUUID(),name,noteIds:ids});});archiveSelection.clear();modal.close();view='organize';render();toast('已归入合集');}catch(err){document.querySelector('#archive-error').textContent=err.message;b.disabled=false;}};}
document.addEventListener('change',e=>{if(e.target.matches('[data-archive-check]')){e.target.checked?archiveSelection.add(e.target.value):archiveSelection.delete(e.target.value);archiveBar();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='archive-filter'){archiveFilter=id;archiveSelection.clear();renderOrganize();}if(action==='archive-save')archiveSave();if(action==='archive-open'){view='library';group=id;render();window.scrollTo(0,0);}if(action==='archive-all'){const archived=new Set(vault.collections.flatMap(c=>c.noteIds)),ns=vault.notes.filter(n=>archiveFilter==='all'||!archived.has(n.id));if(ns.every(n=>archiveSelection.has(n.id)))ns.forEach(n=>archiveSelection.delete(n.id));else ns.forEach(n=>archiveSelection.add(n.id));renderOrganize();}});
let searchFilter={time:'',source:'',kind:'',place:'',from:'',to:''};
function recentNotes(days){return vault.notes.filter(n=>Date.now()-new Date(n.createdAt)<days*86400000);}
function topicSummary(ns){return topics.map(t=>({name:t.name,n:ns.filter(n=>n.topic===t.id).length})).filter(t=>t.n).sort((a,b)=>b.n-a.n).slice(0,2).map(t=>t.name+' '+t.n).join(' · ');}
function recentTheme(){const ns=recentNotes(30),rank=topics.map(t=>({...t,notes:ns.filter(n=>n.topic===t.id)})).sort((a,b)=>b.notes.length-a.notes.length);const t=rank[0];return {...t,image:t.id==='weekend'?'/assets/coast.jpg':t.id==='reading'?'/assets/reading.jpg':safeImage(t.notes.find(n=>n.image)?.image)||'/assets/reading.jpg'};}
function filteredNotes(){return vault.notes.filter(n=>{const f=searchFilter,d=new Date(n.createdAt),now=new Date(),text=[n.title,n.body,n.reason,...n.tags,n.location||''].join(' ');if(f.kind&&n.kind!==f.kind)return false;if(f.source&&n.source!==f.source)return false;if(f.place&&!text.includes(f.place))return false;if(f.time==='today'&&d.toDateString()!==now.toDateString())return false;if(f.time==='week'&&now-d>7*86400000)return false;if(f.time==='month'&&now-d>30*86400000)return false;if(f.time==='year'&&d.getFullYear()!==now.getFullYear()-1)return false;if(f.time==='custom'&&((f.from&&n.createdAt.slice(0,10)<f.from)||(f.to&&n.createdAt.slice(0,10)>f.to)))return false;return true;});}
function extractTags(s){return ['日本','东京','上海','镰仓','海边','列车','雨天','安静','咖啡','旅行','读书','阅读','朋友','周末','餐厅','做饭','灯光','鲜花'].filter(t=>s.includes(t)).slice(0,8);}
function renderLibrary(){if(group){renderGroup();return;}const t=recentTheme(),week=recentNotes(7),month=recentNotes(30);main.innerHTML=`${tabHero('Fragments.','收下喜欢，留住此刻的灵感。')}<button class="scrap-hero" data-action="group" data-id="${t.id}"><div class="scrap-caption"><span>ON MY MIND</span><small>最近在关注</small></div><div class="photo-cluster"><span class="photo-print secondary"><img src="/assets/reading.jpg" alt=""></span><span class="photo-print primary"><img src="${esc(t.image)}" alt=""></span><span class="photo-label">a little inspiration</span></div><div class="scrap-hero-bottom"><div><h2>${esc(t.name)}</h2><p>${t.notes.length} 条记忆，慢慢有了关联</p></div>${icon('chevron')}</div></button><p class="memory-whisper">${month.length?`最近 30 天，你留下了 ${month.length} 个关于${esc(topics.filter(t=>month.some(n=>n.topic===t.id)).slice(0,2).map(t=>t.name).join('和'))}的灵感。`:'下一份喜欢，也会在这里慢慢留下痕迹。'}</p><div class="section-head"><h2>最近留下的</h2><button class="text-btn" data-action="nav" data-view="search">查看全部</button></div><div class="memory-paper">${[...vault.notes].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,6).map(row).join('')||'<div class="empty">点一下 ＋，留下今天的一点喜欢。</div>'}</div><div class="section-head"><h2>慢慢形成的脉络</h2><button class="text-btn" data-action="nav" data-view="organize">整理收藏</button></div><div class="segmented">${topics.map(t=>`<button data-action="group" data-id="${t.id}">${t.name}</button>`).join('')}</div>${vault.collections.map(c=>`<button class="together" data-action="group" data-id="${esc(c.id)}">${safeImage(c.cover)?`<img class="collection-thumb" src="${esc(safeImage(c.cover))}" alt="">`:`<span class="stamp">${icon('users')}</span>`}<span><b>${esc(c.name)}</b><small>${c.noteIds.length} 条记忆 · 我的合集</small></span>${icon('chevron')}</button>`).join('')}<div class="brand-footer">Trace · 溯见</div><p class="library-footer"><button data-action="import">导入完整收藏夹</button> · <button data-action="export">导出备份</button> · <button data-action="about">使用说明</button><br>示例记忆与配图仅用于体验</p>`;}
function renderSearch(){main.innerHTML=`${tabHero('Traces.','描述你还记得的任何细节。')}<div class="search-tools"><form id="search-form"><div class="searchbar">${icon('search')}<input id="query" aria-label="搜索记忆" placeholder="下雨天能坐很久的地方…" value="${esc(query)}" autocomplete="off"><button type="submit" aria-label="搜索">${icon('chevron')}</button></div></form><button class="round" data-action="search-filter" aria-label="筛选">${icon('filter')}</button></div><div class="search-suggestions"><p>试着想起场景，不必记住准确的标题。</p>${['下雨天能坐很久的地方','和朋友一起做的事','之前收藏的旅行清单','让家里舒服一点'].map(q=>`<button data-action="query" data-query="${q}">${q}</button>`).join('')}</div><div id="search-results"></div>`;renderResults();document.querySelector('#search-form').onsubmit=e=>{e.preventDefault();query=document.querySelector('#query').value;renderResults()};document.querySelector('#query').oninput=e=>{query=e.target.value;clearTimeout(renderSearch.timer);renderSearch.timer=setTimeout(renderResults,200)};}
function renderResults(){const el=document.querySelector('#search-results');if(!el)return;const results=searchNotes(filteredNotes(),query);el.innerHTML=`<div class="section-head"><h2>${query?'找到这些线索':'你的记忆'}</h2><div class="browse-tools"><span>${results.length} 条</span><button class="text-btn" data-action="search-mode">${searchEditing?'完成':'选择'}</button></div></div>${results.map(({note:n,evidence},index)=>`<article class="result">${row(n)}${query&&index===0?`<p class="recall-reason">${esc(recallReason(n,query,evidence))}</p>`:''}${searchEditing?`<div class="result-actions"><button class="select-note" data-action="select" data-id="${n.id}" aria-pressed="${selection.has(n.id)}">${icon(selection.has(n.id)?'done':'circle')}${selection.has(n.id)?'已选入计划':'选入计划'}</button></div>`:''}</article>`).join('')||'<div class="empty">暂时没有找到，试试减少筛选条件。<br><button class="text-btn" data-action="reset-filter">清除筛选</button></div>'}${searchEditing&&selection.size?`<div class="selected-bar"><span>已选 ${selection.size} 条记忆</span><button data-action="configure-plan">做个计划</button></div>`:''}`;}
function renderPlans(){legacyrenderPlans();const cards=main.querySelectorAll('.plan-card');const saved=[...cards].map(c=>c.outerHTML).join('');main.innerHTML=`${tabHero('Echoes.','从过往碎片中，得到新的下一步。')}<div class="echo-grid"><button class="echo-card" data-action="echo-plan"><img src="/assets/coast.jpg" alt=""><span><b>帮我做个计划</b><small>把想做的事，排进生活里</small></span></button><button class="echo-card" data-action="echo-summary"><img src="/assets/reading.jpg" alt=""><span><b>最近在关注什么</b><small>回看最近 30 天的脉络</small></span></button></div><form id="echo-form"><div class="searchbar">${icon('spark')}<input name="request" aria-label="回响请求" placeholder="想用哪些记忆做个计划？"><button aria-label="查找相关记忆">${icon('chevron')}</button></div></form><p class="helper">输入场景后先选取相关记忆，再按时间与预算生成安排。不添加未保存的地点。</p><div class="section-head"><h2>留给生活的计划</h2><span class="time-label">${vault.plans.length} 份</span></div>${saved||'<div class="empty">还没有计划。先给一件想做的事，留一点时间。</div>'}`;document.querySelector('#echo-form').onsubmit=e=>{e.preventDefault();query=new FormData(e.currentTarget).get('request');view='search';searchFilter={};searchEditing=true;selection.clear();render();};}
function addMenu(){openModal('添加记忆',`<p class="lede">先留下来，不必现在整理。</p><div class="add-options">${[['link','link','粘贴链接','网页、公众号、小红书等'],['image','image','选择照片','相册、截图，留下这一刻'],['text','text','写一段文字','记录想法或粘贴内容']].map(([type,i,title,sub])=>`<button class="add-option" data-action="add-type" data-id="${type}">${icon(i)}<span><b>${title}</b><small>${sub}</small></span></button>`).join('')}</div><button class="text-btn" data-action="import">已有导出文件？导入完整收藏夹</button>`);}
function detail(id){legacydetail(id);const n=vault.notes.find(x=>x.id===id);if(!n)return;modal.querySelector('#modal-title').textContent='记忆';modal.querySelector('.modal-head .round').insertAdjacentHTML('beforebegin',moreButton('note',id));modal.querySelector('.share-row')?.remove();modal.querySelector('.reason')?.classList.add('personal-thought');modal.querySelector('[data-action="plan-one"]')?.classList.replace('solid','outline');const reason=modal.querySelector('.reason small');if(reason)reason.textContent='你的备注';const body=modal.querySelector('.detail-body');body.insertAdjacentHTML('beforebegin','<h3 class="detail-section">原始内容</h3>');const related=vault.notes.filter(x=>x.id!==id&&x.topic===n.topic).slice(0,3);modal.querySelector('.modal-content').insertAdjacentHTML('beforeend',`${related.length?'<h3 class="detail-section">你可能也会想起</h3>'+related.map(row).join(''):''}`);}
function savedMemory(n){openModal('已保存',`<div class="success-memory">${n.image?`<div class="polaroid"><img src="${esc(n.image)}" alt="刚保存的图片"></div>`:`<div class="polaroid"><p>${esc(n.title)}</p></div>`}<div class="check-mark">${icon('check')}</div><h2>已保存到 Trace</h2><p class="lede">已加入你的记忆。</p><p class="helper">内容已保存，可以通过文字和当时的想法找回。</p><div>${n.tags.map(t=>`<span class="pill-tag">${esc(t)}</span>`).join('')}</div><button class="solid" data-action="close">回到记忆</button><button class="text-btn" data-action="detail" data-id="${n.id}">查看这一条记忆</button></div>`);}
function filterSheet(){const f=searchFilter;const select=(name,label,options)=>`<label class="label">${label}</label><select class="field" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${f[name]===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;openModal('筛选记忆',`<form id="filters-form">${select('time','时间',[['','不限'],['today','今天'],['week','最近一周'],['month','最近一个月'],['year','去年'],['custom','自定义']])}<div class="fields-row"><label class="label">起始日期<input class="field" type="date" name="from" value="${esc(f.from||'')}"></label><label class="label">结束日期<input class="field" type="date" name="to" value="${esc(f.to||'')}"></label></div><p class="helper">日期范围在选择「自定义」时生效。</p>${select('source','来源',[['','全部来源'],...['小红书','公众号','浏览器','网页','聊天','相册','图片','手动记录','随手记','文件导入'].map(x=>[x,x])])}${select('kind','内容类型',[['','全部类型'],['link','网页'],['image','图片'],['text','文字']])}${select('place','地点',[['','不限'],...['东京','上海','镰仓','日本'].map(x=>[x,x])])}<button class="solid">应用筛选</button><button type="button" class="text-btn" data-action="reset-filter">重置筛选</button></form>`);document.querySelector('#filters-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.time==='custom'&&f.from&&f.to&&f.from>f.to){toast('结束日期不能早于起始日期');return;}searchFilter=f;modal.close();view='search';render();};}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{if(action==='search-filter')filterSheet();if(action==='kind-filter'){searchFilter.kind=id;renderSearch();}if(action==='reset-filter'){searchFilter={};modal.close();renderSearch();}if(action==='period'){searchFilter={time:id};query='';view='search';render();}if(action==='echo-plan'){searchEditing=true;selection.clear();query='';searchFilter={};view='search';render();toast('选几条记忆，开始安排');}if(action==='echo-summary'){const ns=recentNotes(30);openModal('最近的记忆脉络',`<p class="lede">根据近 30 天保存内容的主题统计。</p><h2>${esc(topicSummary(ns))||'还没有足够的记忆'}</h2>${ns.slice(0,6).map(row).join('')}`);}if(action==='edit-tags'){const n=vault.notes.find(x=>x.id===id);openModal('编辑标签',`<form id="tags-form"><label class="label">用逗号分开，每条记忆最多 12 个标签</label><input class="field" name="tags" maxlength="500" value="${esc(n.tags.join('，'))}"><button class="solid">保存标签</button></form>`);document.querySelector('#tags-form').onsubmit=async e=>{e.preventDefault();try{const tags=[...new Set(new FormData(e.currentTarget).get('tags').split(/[,，]/).map(t=>t.trim().slice(0,30)).filter(Boolean))].slice(0,12);await commit(v=>v.notes.find(x=>x.id===id).tags=tags);detail(id);}catch(err){fail(err)}};}}catch(err){fail(err)}});
const paths={archive:'M3 4h18v4H3zM5 8v13h14V8M9 12h6',filter:'M4 6h16M7 12h10M10 18h4',audio:'M5 10v4M9 6v12M13 3v18M17 7v10M21 10v4',bookmark:'M6 4h12v17l-6-4-6 4z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',close:'M6 6l12 12M18 6L6 18',chevron:'M9 5l7 7-7 7',back:'M15 5l-7 7 7 7',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',folder:'M3 7V5h7l2 3h9v12H3z',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6L7 7M17 17l1.4 1.4M5.6 18.4L7 17M17 7l1.4-1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',cup:'M4 6h13v9a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5zM17 7h2a3 3 0 0 1 0 6h-2M8 2v1M12 2v1',book:'M12 5v16M12 6C9 3 4 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-2-1-7-1-10 2',home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-4M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 3a4 4 0 0 1 0 8',check:'M5 12l4 4L19 6',circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',done:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M7 12l3 3 7-7',plan:'M8 3v4M16 3v4M3 10h18M4 5h16a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1M7 15l3 3 7-5',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',image:'M3 3h18v18H3zM3 17l6-6 5 5 3-3 4 4M16 7h.01',text:'M4 4h16M12 4v17M8 21h8',upload:'M12 16V3M7 8l5-5 5 5M4 15v6h16v-6',download:'M12 3v13M7 11l5 5 5-5M4 17v4h16v-4',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7h.01',share:'M12 16V3M7 8l5-5 5 5M5 12v9h14v-9'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.bookmark}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
const safeImage=v=>/^(?:\/assets\/[\w.-]+|data:image\/(?:jpeg|png|webp);base64,[a-zA-Z0-9+/=]+)$/.test(v||'')?v:'';
const main=document.querySelector('#main'),header=document.querySelector('#header'),nav=document.querySelector('#nav'),modal=document.querySelector('#modal');
let vault,view='library',filter='all',group=null,query='',selection=new Set(),busy=false;
const vaultKey='trace-sujian-vault-v1',sharesKey='trace-sujian-shares-v1';
async function asDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(file);});}
async function api(path,options={}){
  if(path==='/api/vault'){
    if((options.method||'GET')==='GET'){try{return JSON.parse(localStorage.getItem(vaultKey))||newVault();}catch{return newVault();}}
    localStorage.setItem(vaultKey,options.body);return {ok:true};
  }
  if(path==='/api/upload'&&options.method==='POST')return {image:await asDataUrl(options.body)};
  if(path==='/api/share'&&options.method==='POST'){
    const id=crypto.randomUUID(),shares=JSON.parse(localStorage.getItem(sharesKey)||'{}');
    shares[id]=JSON.parse(options.body);localStorage.setItem(sharesKey,JSON.stringify(shares));
    return {url:location.origin+location.pathname+'?share='+id};
  }
  if(path.startsWith('/api/share/')){const id=decodeURIComponent(path.slice('/api/share/'.length)),shares=JSON.parse(localStorage.getItem(sharesKey)||'{}');if(shares[id])return shares[id];throw Error('没有找到这个合集');}
  throw Error('当前操作暂不可用');
}
async function commit(change){if(busy)throw Error('正在保存，请稍候');busy=true;try{const next=structuredClone(vault);change(next);await api('/api/vault',{method:'PUT',body:JSON.stringify(next)});vault=next;}finally{busy=false}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}
function fail(e){toast(e.message||'暂时无法完成');}
const topic=n=>topics.find(t=>t.id===n.topic)||topics[0];
function thumb(n,cls='thumb'){if(n.example&&!n.image&&['reading','weekend'].includes(n.topic))n={...n,image:n.topic==='reading'?'/assets/reading.jpg':'/assets/coast.jpg'};return safeImage(n.image)?`<img class="${cls}" src="${esc(n.image)}" alt="${esc(n.title)}" style="object-position:${['50% 82%','15% 18%','100% 45%'].includes(n.crop)?n.crop:'center'}">`:`<span class="${cls} text-thumb ${topic(n).color}">${icon(topic(n).icon)}</span>`;}
function row(n){return `<button class="note-row" data-action="detail" data-id="${esc(n.id)}">${thumb(n)}<span class="row-copy"><h3>${esc(n.title)}</h3><p>${esc(n.reason||n.body)}</p><span class="meta"><span class="source">${esc(n.source)}</span><span>·</span><span>${esc(n.createdAt?.slice(5,10)||'刚刚')}</span>${n.example?'<span class="example">示例</span>':''}</span><span class="memory-tags">${n.tags.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</span></span></button>`;}
function render(){renderUndo();header.innerHTML=`<button class="round" data-action="about" aria-label="使用说明">${icon('info')}</button><span class="wordmark">${{library:'记忆',search:'追溯',plans:'回响',organize:'整理'}[view]}</span><span class="header-spacer" aria-hidden="true"></span>`;nav.innerHTML=`<div class="bottom-nav">${[['library','folder','记忆'],['search','search','追溯'],['plans','spark','回响']].map(([v,i,n])=>`<button data-action="nav" data-view="${v}" class="${(view===v||(view==='organize'&&v==='library'))?'active':''}" aria-label="${n}" title="${n}" aria-current="${view===v?'page':'false'}">${icon(i)}</button>`).join('')}<button class="nav-add" data-action="add" aria-label="添加记忆">${icon('plus')}</button></div>`;if(view==='library')renderLibrary();if(view==='search')renderSearch();if(view==='plans')renderPlans();if(view==='organize')renderOrganize();}
function renderGroup(){const t=topics.find(t=>t.id===group),c=vault.collections.find(c=>c.id===group);if(!t&&!c){group=null;renderLibrary();return;}const nn=t?vault.notes.filter(n=>n.topic===t.id&&!vault.removed?.[t.id]?.includes(n.id)):vault.notes.filter(n=>c.noteIds.includes(n.id));main.innerHTML=`<div class="collection-top"><button class="text-btn" data-action="home">${icon('back')}所有记忆</button>${moreButton(t?'topic':'collection',group)}</div>${safeImage(c?.cover)?`<div class="group-cover"><img src="${esc(safeImage(c.cover))}" alt="合集封面"></div>`:`<div class="group-collage"><img src="${t?.id==='weekend'?'/assets/coast.jpg':'/assets/reading.jpg'}" alt=""><img src="${esc(safeImage(nn.find(n=>n.image)?.image)||'/assets/reading.jpg')}" alt=""></div>`}<h1>${esc(t?.name||c.name)}</h1><p class="lede">${t?'这些记忆具有共同的主题，因此聚在这里。当前依据主题标签归组，你随时可以调整。':'留下一起想做的事，让下一次见面有迹可循。'}</p><div class="share-row"><button class="outline" data-action="share">${icon('share')}分享合集</button></div><div class="section-head"><h2>${nn.length} 条灵感</h2><button class="text-btn" data-action="select-group">选入计划</button></div>${nn.map(row).join('')||'<div class="empty">还没有收藏，添加一点灵感吧。</div>'}`;}
function legacyrenderPlans(){main.innerHTML=`<div class="intro-row"><h1>让喜欢发生。</h1>${icon('plan')}</div><p class="lede">留一点时间，做收藏里想做的事。</p>${vault.plans.length?vault.plans.map(p=>`<article class="plan-card"><div class="plan-topline"><span class="eyebrow">A LITTLE PLAN</span><span class="count-badge">${p.items.filter(i=>i.done).length} / ${p.items.length}</span></div><h3>${esc(p.title)}</h3><div class="meta">约 ${Math.round(p.elapsed/6)/10} 小时 · 预算参考 ¥${p.total}</div><div class="progress"><i style="width:${p.items.length?p.items.filter(i=>i.done).length/p.items.length*100:0}%"></i></div>${p.items.map((i,j)=>`<div class="plan-item"><span class="clock">${esc(i.time)}</span>${vault.notes.find(n=>n.id===i.noteId)?`<button class="timeline-photo" data-action="detail" data-id="${esc(i.noteId)}" aria-label="查看 ${esc(i.title)} 的原收藏">${thumb(vault.notes.find(n=>n.id===i.noteId),'timeline-thumb')}</button>`:''}<span class="task ${i.done?'done':''}"><h3>${esc(i.title)}</h3><small>${i.minutes} 分钟 · ¥${i.cost} 参考${vault.notes.some(n=>n.id===i.noteId)?` · <button class="text-btn" data-action="detail" data-id="${esc(i.noteId)}">查看来源</button>`:''}</small></span><button data-action="toggle-task" data-id="${p.id}" data-index="${j}" aria-label="${i.done?'标记未完成':'标记完成'} ${esc(i.title)}">${icon(i.done?'done':'circle')}</button></div>`).join('')}<p class="plan-note">时间与预算为计划参考；相邻事项预留 15 分钟，未计算真实交通。店铺地址、营业时间与预约情况请出发前核实。${p.deferred.length?` 另有 ${p.deferred.length} 条因预算或时间限制暂未安排。`:''}</p><button class="text-btn" data-action="export-plan" data-id="${p.id}">${icon('download')}导出行动清单</button></article>`).join(''):`<div class="empty">${icon('plan')}<b>下一次小出发，从收藏开始。</b>找到几条想实现的灵感，<br>把它们排进你的时间里。<button class="solid" data-action="nav" data-view="search">去找一点灵感</button></div>`}`;}
function openModal(title,body){activeImagePicker?.dispose();activeImagePicker=null;modal.innerHTML=`<div class="modal-content"><div class="handle"></div><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="round" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}</div>`;if(!modal.open)modal.showModal();}
function moreButton(kind,id){return `<button class="round more-button" data-action="record-menu" data-kind="${kind}" data-id="${esc(id)}" aria-label="${kind==='note'?'记忆':'合集'}更多操作" aria-haspopup="dialog">⋯</button>`;}
function imagePickerMarkup(current,label){return `<section class="image-editor"><img data-photo-preview alt="${label}预览" hidden><label class="outline image-upload">更换${label}<input data-photo-input type="file" accept="image/jpeg,image/png,image/webp" aria-label="更换${label}"></label><button type="button" class="text-btn" data-photo-reset hidden>取消本次换图</button><p class="helper">JPG、PNG、WebP · 5MB 以内，保存后生效</p><p data-photo-error role="alert"></p></section>`;}
function attachImagePicker(form,current){const picker=bindImagePicker(form,safeImage(current)||'',file=>api('/api/upload',{method:'POST',headers:{'Content-Type':file.type},body:file}));activeImagePicker=picker;return picker;}
modal.addEventListener('close',()=>{activeImagePicker?.dispose();activeImagePicker=null;});
function returnRecord(kind,id){if(kind==='note')detail(id);else{modal.close();group=id;view='library';render();}}
function recordMenu(kind,id){
  const n=kind==='note'?vault.notes.find(n=>n.id===id):kind==='topic'?topics.find(t=>t.id===id):vault.collections.find(c=>c.id===id);if(!n)return;
  const item=(action,title,sub,cls='')=>`<button class="${cls}" data-action="${action}" data-kind="${kind}" data-id="${esc(id)}"><b>${title}</b><small>${sub}</small></button>`;
  openModal('更多操作',`<p class="menu-context">${esc(n.title||n.name)}</p><div class="record-menu">${kind==='topic'?item('edit-group','调整内容','修改这个自动主题下的记忆'):item('record-edit','编辑',kind==='note'?'图片、标题、正文、想法和标签':'修改封面、合集名称与内容')+item('record-move','移动',kind==='note'?'移动到其他合集或移出合集':'将合集中的记忆移至另一合集')+item('record-delete','删除',kind==='note'?'删除后可撤销':'只删除合集，保留全部记忆','danger-text')}</div><button class="outline" data-action="record-return" data-kind="${kind}" data-id="${esc(id)}">返回</button>`);
}
function editCollection(id){const c=vault.collections.find(c=>c.id===id);if(!c)return;openModal('编辑合集',`<form id="rename-form">${imagePickerMarkup(c.cover,'封面')}<label class="label" for="collection-name">合集名称</label><input id="collection-name" class="field" name="name" value="${esc(c.name)}" maxlength="120" required><div class="share-row"><button class="outline" type="button" data-action="record-return" data-kind="collection" data-id="${id}">取消</button><button class="solid">保存修改</button></div><div class="form-error" role="alert"></div></form><button class="text-btn" data-action="edit-group">管理合集中的记忆</button>`);const picker=attachImagePicker(document.querySelector('#rename-form'),c.cover);document.querySelector('#rename-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.solid');b.disabled=true;try{const name=f.elements.name.value.trim();if(!name)throw Error('给合集起个名字吧');const cover=await picker.value();await commit(v=>{Object.assign(v.collections.find(x=>x.id===id),{name,cover});});returnRecord('collection',id);toast('合集已更新');}catch(err){f.querySelector('.form-error').textContent=err.message;b.disabled=false;}};}
function moveSheet(kind,id){const options=vault.collections.filter(c=>kind==='note'||c.id!==id);openModal('移动到哪里？',`<form id="move-form"><p class="lede">${kind==='note'?'将移出原有的自建合集，保存到所选位置。主题归组不变。':'移动其中全部记忆，原合集保留为空合集。其他合集中的归档不受影响。'}</p><label class="label" for="move-target">目标位置</label><select id="move-target" name="target" class="field"><option value="">仅保留在所有记忆中</option>${options.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><p class="helper">记忆及其备注不会被删除。</p><div class="form-error" role="alert"></div><div class="share-row"><button class="outline" type="button" data-action="record-return" data-kind="${kind}" data-id="${id}">取消</button><button class="solid">确认移动</button></div></form>`);document.querySelector('#move-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.solid');b.disabled=true;try{await commit(v=>moveRecord(v,kind,id,f.elements.target.value));render();returnRecord(kind,id);toast('已更新归档位置');}catch(err){f.querySelector('.form-error').textContent=err.message;b.disabled=false;}};}
function confirmDelete(kind,id){const n=(kind==='note'?vault.notes:vault.collections).find(x=>x.id===id);if(!n)return;openModal(kind==='note'?'删除这条记忆？':'删除这个合集？',`<p class="delete-name">${esc(n.title||n.name)}</p><p class="lede">${kind==='note'?'会从所有合集移除这条记忆。已有计划和分享快照不会改动。':'只删除合集，里面的记忆与备注会全部保留，可在「记忆」或「追溯」中找到。'}</p><p class="helper">可撤销最近 10 次删除，刷新页面后仍保留。</p><div id="delete-error" role="alert"></div><div class="share-row"><button class="outline" data-action="record-return" data-kind="${kind}" data-id="${id}" autofocus>先留着</button><button class="outline danger-text" id="confirm-delete">确认删除</button></div>`);document.querySelector('#confirm-delete').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await commit(v=>removeRecord(v,kind,id));selection.delete(id);archiveSelection.delete(id);if(kind==='collection'){group=null;view='library';}modal.close();render();renderUndo(true);toast(kind==='note'?'记忆已删除，可在下方撤销':'合集已删除，其中的记忆已保留');}catch(err){document.querySelector('#delete-error').textContent=err.message;b.disabled=false;}};}
function renderUndo(show=false){clearTimeout(renderUndo.timer);let el=document.querySelector('#undo-notice');if(!el){el=document.createElement('aside');el.id='undo-notice';el.setAttribute('aria-label','撤销删除');document.body.append(el);}const entry=vault?.undoHistory?.at(-1);el.hidden=!show||!entry;if(show&&entry){el.innerHTML=`<span>已删除${entry.kind==='note'?'记忆':'合集'}<small>${esc(entry.data.title||entry.data.name)}</small></span><button data-action="undo-delete">撤销</button><button data-action="dismiss-undo" aria-label="关闭删除提示">×</button>`;renderUndo.timer=setTimeout(()=>{el.hidden=true;},8000);}}
function undoHistory(){const entry=vault.undoHistory?.at(-1);openModal('最近删除',entry?`<p class="lede">保留最近 10 次删除，可按删除顺序逐次撤销。</p><p class="delete-name">${esc(entry.data.title||entry.data.name)}</p><p class="helper">恢复内容及原有归档关系。</p><button class="outline" data-action="undo-delete">恢复这${entry.kind==='note'?'条记忆':'个合集'}</button>`:'<p class="lede">没有需要恢复的内容。</p>');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,kind,id}=b.dataset;try{if(action==='dismiss-undo')renderUndo();if(action==='undo-history')undoHistory();if(action==='record-menu')recordMenu(kind,id);if(action==='record-return')returnRecord(kind,id);if(action==='record-edit'){if(kind==='note')editNote(id);else editCollection(id);}if(action==='record-move')moveSheet(kind,id);if(action==='record-delete')confirmDelete(kind,id);if(action==='undo-delete'){b.disabled=true;await commit(v=>restoreLast(v));render();if(modal.open)undoHistory();toast('已恢复内容与归档关系');}}catch(err){b.disabled=false;fail(err);}});
function legacydetail(id){const n=vault.notes.find(n=>n.id===id);if(!n)return;openModal('这一条喜欢',`${safeImage(n.image)?thumb(n,'detail-image'):''}<h2 class="detail-title">${esc(n.title)}</h2><div class="meta">${esc(n.source)} · ${esc(n.createdAt?.slice(0,10))}${n.example?'<span class="example">示例内容</span>':''}</div><div class="reason"><small>当时为什么收藏</small><p>${esc(n.reason||'还没留下备注。记录一点当时的想法，下次更容易找回。')}</p></div><div class="detail-body">${esc(n.body)}</div><div>${n.tags.map(t=>`<span class="pill-tag">${esc(t)}</span>`).join('')}</div>${safeUrl(n.url)?`<p><a class="text-btn" href="${esc(safeUrl(n.url))}" target="_blank" rel="noopener noreferrer">${icon('link')}打开原始链接</a></p>`:''}<div class="share-row"><button class="outline" data-action="edit-note" data-id="${n.id}">修改备注</button><button class="outline" data-action="add-to-collection" data-id="${n.id}">加入合集</button></div><button class="solid" data-action="plan-one" data-id="${n.id}">${icon('plan')}把它安排进生活</button>`);}
function addForm(type){if(type==='import'){importForm();return;}openModal(type==='link'?'保存链接':type==='image'?'保存图片':'留一段文字',`<form id="add-form">${type==='link'?'<label class="label" for="url">原始链接</label><input class="field" id="url" name="url" type="url" placeholder="https://…" required><p class="helper">保留原始链接，也可以粘贴正文，方便下次找回。</p>':''}${type==='image'?'<label class="label" for="photo">选择图片</label><input class="field" id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required><p class="helper">支持 5MB 以内的 JPG、PNG、WebP，留一句想法，下次更容易找回。</p><img id="preview" class="preview-image" hidden alt="图片预览">':''}<label class="label" for="body">${type==='text'?'想留下的内容':'补充文字线索 · 选填'}</label><textarea class="field" id="body" name="body" maxlength="20000" placeholder="它是什么？有什么细节让你想留住？" ${type==='text'?'required':''}></textarea><label class="label" for="reason">当时的想法 <span class="muted">· 选填</span></label><textarea class="field" id="reason" name="reason" maxlength="2000" placeholder="比如：下次朋友来上海，想带她去"></textarea><div id="form-error"></div><button class="solid" type="submit">保存记忆</button></form>`);let previewUrl;if(type==='image')document.querySelector('#photo').onchange=e=>{if(previewUrl)URL.revokeObjectURL(previewUrl);if(e.target.files[0]){previewUrl=URL.createObjectURL(e.target.files[0]);const img=document.querySelector('#preview');img.src=previewUrl;img.hidden=false}};document.querySelector('#add-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),body=f.get('body').trim(),reason=f.get('reason').trim();if(type==='text'&&!body)throw Error('写下一点想保存的内容吧');const title=(body||reason).split(/[。！？\n]/)[0].slice(0,40)||(type==='image'?'一张想留住的照片':'保存的网页链接');let image='';if(type==='image'){const photo=f.get('photo');if(photo.size>5*1024*1024)throw Error('请选择 5MB 以内的图片');const result=await api('/api/upload',{method:'POST',headers:{'Content-Type':photo.type},body:photo});image=result.image;}const url=type==='link'?safeUrl(f.get('url')):'';if(type==='link'&&!url)throw Error('请输入完整的网页链接');const source=type==='link'?(url.includes('xiaohongshu')||url.includes('xhslink')?'小红书':url.includes('weixin')?'公众号':'网页'):type==='image'?'图片':'随手记';const n={id:crypto.randomUUID(),title,body,reason,source,url,image,topic:inferTopic(title+body+reason),tags:extractTags(body+reason),kind:type,example:false,createdAt:new Date().toISOString(),minutes:45,cost:0};await commit(v=>v.notes.unshift(n));modal.close();view='library';group=null;filter='all';render();savedMemory(n);}catch(err){form.querySelector('#form-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}finally{btn.disabled=false;if(previewUrl)URL.revokeObjectURL(previewUrl)}};}
function importForm(){openModal('导入完整收藏夹',`<p>把已经导出的收藏放在一起，保留标题、正文、原始链接和备注。</p><form id="import-form"><label class="label">选择 JSON 文件</label><input class="field" name="file" type="file" accept=".json,application/json" required><p class="helper">接受本产品的导出文件，或包含 title、body、url、reason 的数组；单次最多 200 条。不支持自动同步平台账号。</p><button class="text-btn" type="button" data-action="template">${icon('download')}下载格式示例</button><div id="import-error"></div><button class="solid">导入收藏</button></form>`);document.querySelector('#import-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('.solid');btn.disabled=true;try{const file=form.elements.file.files[0];if(file.size>1500000)throw Error('请选择 1.5MB 以内的 JSON 文件');const parsed=JSON.parse(await file.text());const records=Array.isArray(parsed)?parsed:parsed.notes;if(!Array.isArray(records)||!records.length||records.length>200)throw Error('文件需包含 1–200 条收藏');const fresh=[];let duplicates=0;for(const n of records){if(typeof n.title!=='string'||!n.title.trim()||typeof(n.body??n.content??'')!=='string')throw Error('每条收藏需要文字标题和正文');const url=safeUrl(n.url),body=String(n.body??n.content??'').slice(0,20000),title=n.title.slice(0,160),reason=String(n.reason||'').slice(0,2000);if([...vault.notes,...fresh].some(x=>url?x.url===url:x.title===title&&x.body===body)){duplicates++;continue;}fresh.push({id:crypto.randomUUID(),title,body,reason,url,source:String(n.source||'文件导入').slice(0,60),topic:topics.some(t=>t.id===n.topic)?n.topic:inferTopic(title+body+reason),tags:Array.isArray(n.tags)?n.tags.filter(t=>typeof t==='string').slice(0,12).map(t=>t.slice(0,60)):[],kind:'text',image:'',example:false,createdAt:new Date().toISOString(),minutes:45,cost:0});}if(fresh.length)await commit(v=>v.notes.unshift(...fresh));modal.close();view='library';group=null;render();toast(`已导入 ${fresh.length} 条${duplicates?`，跳过 ${duplicates} 条重复内容`:''}`);}catch(err){form.querySelector('#import-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}finally{btn.disabled=false}};}
function editNote(id){
const n=vault.notes.find(x=>x.id===id);if(!n)return;
openModal('编辑记忆',`<form id="edit-form">${imagePickerMarkup(n.image,'图片')}<label class="label" for="edit-title">标题</label><input id="edit-title" class="field" name="title" required maxlength="160" value="${esc(n.title)}"><label class="label" for="edit-reason">收藏当下的想法</label><textarea id="edit-reason" class="field" name="reason" maxlength="2000">${esc(n.reason)}</textarea><label class="label" for="edit-url">原帖链接（选填）</label><input id="edit-url" class="field" name="url" type="url" inputmode="url" maxlength="4096" placeholder="https://…" value="${esc(n.url||'')}" aria-describedby="edit-url-hint"><p id="edit-url-hint" class="helper">粘贴完整网页链接；清空并保存可移除来源链接。</p><label class="label" for="edit-body">原始内容</label><textarea id="edit-body" class="field" name="body" maxlength="20000">${esc(n.body)}</textarea><label class="label" for="edit-tags">标签 · 用逗号分开</label><input id="edit-tags" class="field" name="tags" maxlength="500" value="${esc(n.tags.join('，'))}"><label class="label" for="edit-topic">主题</label><select id="edit-topic" class="field" name="topic">${topics.map(t=>`<option value="${t.id}" ${n.topic===t.id?'selected':''}>${t.name}</option>`).join('')}</select><div id="edit-error" role="alert"></div><div class="share-row"><button type="button" class="outline" data-action="detail" data-id="${id}">取消</button><button class="solid">保存修改</button></div></form>`);
const picker=attachImagePicker(document.querySelector('#edit-form'),n.image);document.querySelector('#edit-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.solid');b.disabled=true;try{const title=f.elements.title.value.trim();if(!title)throw Error('请填写标题');const tags=[...new Set(f.elements.tags.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean))];if(tags.length>12||tags.some(s=>s.length>60))throw Error('最多 12 个标签，每个不超过 60 字');const rawUrl=f.elements.url.value.trim(),url=safeUrl(rawUrl);if(rawUrl&&!url)throw Error('请输入以 https:// 或 http:// 开头的完整网页链接');const image=await picker.value();await commit(v=>{const x=v.notes.find(x=>x.id===id);Object.assign(x,{image,title,url,reason:f.elements.reason.value,body:f.elements.body.value,tags,topic:f.elements.topic.value});});render();detail(id);toast('修改已保存');}catch(err){f.querySelector('#edit-error').textContent=err.message;b.disabled=false;}};
}
function configurePlan(){const notes=vault.notes.filter(n=>selection.has(n.id));if(!notes.length){toast('先选几条想做的事');return;}openModal('给喜欢留一点时间',`<p class="lede">选了 ${notes.length} 条收藏，按你的时间与预算安排。</p><form id="plan-form"><label class="label">计划名称</label><input class="field" name="title" required maxlength="80" value="留给喜欢的半天"><div class="fields-row"><div><label class="label">开始时间</label><input class="field" name="start" type="time" value="10:00" required></div><div><label class="label">空闲时长</label><select class="field" name="hours"><option value="2">2 小时</option><option value="4" selected>4 小时</option><option value="6">6 小时</option></select></div></div><label class="label">总预算（元）</label><input class="field" name="budget" type="number" min="0" max="100000" value="200" required><p class="helper">可取消不想安排的内容。示例费用用于体验；新增内容默认为 ¥0 占位，需自行确认。</p>${notes.map(n=>`<label class="check-row"><input type="checkbox" name="notes" value="${n.id}" checked>${esc(n.title)}</label>`).join('')}<div id="plan-error"></div><button class="solid">生成并保存计划</button></form>`);document.querySelector('#plan-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('.solid');btn.disabled=true;try{const f=new FormData(form),ids=f.getAll('notes');if(!ids.length)throw Error('至少选一条收藏');const plan=buildPlan(notes.filter(n=>ids.includes(n.id)),{title:f.get('title'),start:f.get('start'),hours:Number(f.get('hours')),budget:Number(f.get('budget'))});if(!plan.items.length)throw Error('时间或预算不够安排所选内容，请调整后重试');await commit(v=>v.plans.unshift(plan));modal.close();selection.clear();view='plans';render();window.scrollTo(0,0);toast('计划已保存，一点点实现它');}catch(err){form.querySelector('#plan-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}finally{btn.disabled=false}};}
function collectionForm(noteId){openModal(noteId?'加入一个合集':'新的共同灵感',`<form id="collection-form">${noteId&&vault.collections.length?`<label class="label">选择已有合集</label><select class="field" name="existing"><option value="">新建合集</option>${vault.collections.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select>`:''}<label class="label">新合集名称</label><input class="field" name="name" maxlength="80" placeholder="比如：下次和朋友见面"><p class="helper">可以分享合集快照，让朋友打开或收进自己的收藏。</p><div id="collection-error"></div><button class="solid">${noteId?'加入合集':'创建合集'}</button></form>`);document.querySelector('#collection-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{const existing=form.elements.existing?.value,name=form.elements.name.value.trim();if(!existing&&!name)throw Error('给合集起个名字吧');let id=existing||crypto.randomUUID();await commit(v=>{if(existing){const c=v.collections.find(c=>c.id===existing);if(!c.noteIds.includes(noteId))c.noteIds.push(noteId);}else v.collections.push({id,name,noteIds:noteId?[noteId]:[]})});modal.close();group=id;view='library';render();toast('合集已保存');}catch(err){form.querySelector('#collection-error').textContent=err.message}};}
function manageGroup(){const t=topics.find(t=>t.id===group),c=vault.collections.find(c=>c.id===group);const selected=new Set(t?vault.notes.filter(n=>n.topic===t.id&&!vault.removed?.[t.id]?.includes(n.id)).map(n=>n.id):c.noteIds);openModal('管理合集内容',`<form id="manage-form">${vault.notes.map(n=>`<label class="check-row"><input type="checkbox" name="notes" value="${n.id}" ${selected.has(n.id)?'checked':''}>${esc(n.title)}</label>`).join('')}<button class="solid">保存合集</button><div id="manage-error"></div></form>`);document.querySelector('#manage-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,ids=new FormData(form).getAll('notes');try{await commit(v=>{if(c)v.collections.find(x=>x.id===c.id).noteIds=ids;else {v.removed??={};v.removed[t.id]=v.notes.filter(n=>n.topic===t.id&&!ids.includes(n.id)).map(n=>n.id);ids.forEach(id=>v.notes.find(n=>n.id===id).topic=t.id);}});modal.close();render();toast('已更新合集');}catch(err){form.querySelector('#manage-error').textContent=err.message}};}
async function shareGroup(){const t=topics.find(t=>t.id===group),c=vault.collections.find(c=>c.id===group);const notes=t?vault.notes.filter(n=>n.topic===t.id&&!vault.removed?.[t.id]?.includes(n.id)):vault.notes.filter(n=>c.noteIds.includes(n.id));openModal('分享这一组喜欢',`<p>创建「${esc(t?.name||c.name)}」的快照链接，包含 ${notes.length} 条收藏的文字、备注和原始链接。</p><p class="helper">你上传的私人图片不会进入分享快照。链接访问仍遵循网站访问权限；后续修改不会自动同步到快照。</p><button class="solid" id="share-confirm">创建分享链接</button><div id="share-result"></div>`);document.querySelector('#share-confirm').onclick=async e=>{e.target.disabled=true;try{const r=await api('/api/share',{method:'POST',body:JSON.stringify({name:t?.name||c.name,notes})});document.querySelector('#share-result').innerHTML=`<label class="label">复制链接，发给对方</label><input class="field" id="share-url" readonly value="${esc(r.url)}"><button class="outline" style="margin-top:12px" id="copy-share">复制链接</button>`;document.querySelector('#copy-share').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast('链接已复制')}catch{document.querySelector('#share-url').select();toast('请长按或使用复制快捷键')}};e.target.textContent='分享快照已创建';}catch(err){document.querySelector('#share-result').textContent=err.message;e.target.disabled=false}};}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function sharedSnapshot(id){try{const data=await api('/api/share/'+encodeURIComponent(id));openModal(data.name,`<p class="lede">对方想和你分享的 ${data.notes.length} 条灵感。</p>${data.notes.map(n=>`<div class="note-row"><span class="row-copy"><h3>${esc(n.title)}</h3><p>${esc(n.reason||n.body)}</p></span></div>`).join('')}<button class="solid" id="accept-share">收进我的收藏</button><div id="accept-error"></div>`);document.querySelector('#accept-share').onclick=async e=>{e.target.disabled=true;try{await commit(v=>{const ids=[];for(const n of data.notes){let existing=v.notes.find(x=>n.url?x.url===n.url:x.title===n.title&&x.body===n.body);if(existing)ids.push(existing.id);else{const id=crypto.randomUUID();v.notes.unshift({...n,id,image:safeImage(n.image),example:false});ids.push(id)}}v.collections.push({id:crypto.randomUUID(),name:data.name,noteIds:ids});});modal.close();history.replaceState({},'',location.pathname);render();toast('已收进你的收藏');}catch(err){document.querySelector('#accept-error').textContent=err.message;e.target.disabled=false}};}catch(e){fail(e)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{switch(action){case 'home':view='library';group=null;render();window.scrollTo(0,0);break;case 'nav':searchEditing=false;selection.clear();archiveEditing=false;archiveSelection.clear();view=b.dataset.view;group=null;render();window.scrollTo(0,0);break;case 'close':modal.close();break;case 'add':addMenu();break;case 'add-type':addForm(id);break;case 'filter':filter=id;renderLibrary();break;case 'group':group=id;renderLibrary();window.scrollTo(0,0);break;case 'detail':detail(id);break;case 'query':query=b.dataset.query;searchFilter={};renderSearch();break;case 'select':selection.has(id)?selection.delete(id):selection.add(id);renderResults();break;case 'plan-one':selection=new Set([id]);configurePlan();break;case 'configure-plan':configurePlan();break;case 'edit-note':editNote(id);break;case 'collection':collectionForm();break;case 'add-to-collection':collectionForm(id);break;case 'edit-group':manageGroup();break;case 'share':shareGroup();break;case 'select-group':{const t=topics.find(t=>t.id===group),c=vault.collections.find(c=>c.id===group);selection=new Set(t?vault.notes.filter(n=>n.topic===group&&!vault.removed?.[group]?.includes(n.id)).map(n=>n.id):c.noteIds);configurePlan();break;}case 'toggle-task':await commit(v=>{const item=v.plans.find(p=>p.id===id).items[Number(b.dataset.index)];item.done=!item.done});renderPlans();break;case 'import':importForm();break;case 'export':download('我的收藏.json',JSON.stringify({notes:vault.notes.map(n=>({...n,image:''}))},null,2));toast('已导出文字、备注和来源链接');break;case 'template':download('收藏导入示例.json',JSON.stringify([{title:'想留住的内容',body:'正文或你记住的细节',url:'',reason:'当时为什么想保存',source:'随手记'}],null,2));break;case 'export-plan':{const p=vault.plans.find(p=>p.id===id);download(p.title+'.txt',p.title+'\n\n'+p.items.map(i=>`${i.done?'☑':'☐'} ${i.time} ${i.title}（${i.minutes} 分钟，参考 ¥${i.cost}）`).join('\n')+'\n\n时间与费用仅供计划参考，出发前请核实地址、营业及预约信息。','text/plain;charset=utf-8');break;}case 'about':openModal('关于 Trace · 溯见',`<p>收下喜欢，留住此刻的想法。</p><p>把内容归入合集，从标题、正文或当时的想法找回，再将收藏变成下一步。</p><p class="helper">内容保存在网站中，通过当前浏览器识别你的收藏库。请定期导出备份；清除浏览器 Cookie 后会进入新的收藏库。</p><p class="helper">分享生成合集快照，访问遵循网站权限。示例收藏与封面供体验使用。</p><button class="outline" data-action="undo-history">最近删除 · 恢复内容</button>`);break;}}catch(err){fail(err)}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
async function init(){try{vault=await api('/api/vault');render();const share=new URL(location.href).searchParams.get('share');if(share)sharedSnapshot(share);}catch(e){main.innerHTML=`<div class="empty"><b>收藏库暂时没有连上</b><p>${esc(e.message)}</p><button class="solid" id="retry">重新连接</button></div>`;document.querySelector('#retry').onclick=init;}}init();
